import{_ as e,o as n,c as a,a2 as d}from"./chunks/framework.BPyF_sP4.js";const A=JSON.parse('{"title":"构建篇导读","description":"","frontmatter":{"title":"构建篇导读","bookSource":"02-build/README.md","bookPart":"构建篇","readingMinutes":3,"prev":{"text":"第 2 章 Agentic Application 参考架构","link":"/architecture/chapter-02.html"},"next":{"text":"第 3 章 范式：Harness 的主流构建方式和责任边界","link":"/build/chapter-03.html"},"editLink":true},"headers":[],"relativePath":"build/index.md","filePath":"02-build/README.md","lastUpdated":1790038459000}'),r={name:"build/index.md"};function o(i,t,s,l,c,p){return n(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="构建篇导读" tabindex="-1">构建篇导读 <a class="header-anchor" href="#构建篇导读" aria-label="Permalink to &quot;构建篇导读&quot;">​</a></h1><p>上一篇确立了架构对象与责任划分，本篇进入生命周期的第二个阶段。构建阶段的核心工作有两项：决定 Harness 由谁实现，以及把模型的离散判断组织为可持续推进、可中断恢复、可验证结束的任务过程。</p><p>Coding Agent 为这项工作提供了一个可观察的工程样本。在代码、文件与测试构成的环境中，模型可以通过工具持续行动，系统也可以用编译、测试和文件差异验证结果。它说明模型能力只有经过上下文组织、任务循环、状态管理、工具执行、权限控制与结果验证，才可能稳定转化为任务结果。但编码场景不能替代全部企业任务：审批、交易、客服与运营具有不同的业务状态、权限边界与成功标准，企业应复用其中可泛化的 Harness 机制，而非照搬一套 Coding Agent 流程。</p><p>构建是本书五个持续责任域中的 Agent 构建与编排域。这里的构建不是一次性开发活动，被构建出的编排逻辑会在每次任务运行时持续工作，其质量直接决定运行篇要承载什么、治理篇要观测什么、调优篇能改什么。同时，本篇只描述并绑定可用能力，物理执行、状态落盘与环境隔离由运行篇承担，这条边界贯穿四章。</p><table tabindex="0"><thead><tr><th>对应章节</th><th>主线</th><th>构建对象或问题</th><th>主要机制</th></tr></thead><tbody><tr><td>第 3 章</td><td>范式：Harness 由谁实现</td><td>定制深度、数据边界、运行责任与交付方式的取舍。</td><td>四类构建入口：高代码框架、产品化 Harness（Coding Agent CLI / SDK 与工作区助手）、Managed Agents、Agent 云产品；Agent Platform 的规模化交付与多源纳管。</td></tr><tr><td>第 4 章</td><td>工程契约：任务</td><td>任务如何推进、中断如何恢复、完成如何判定。</td><td>Agent Loop 与任务状态机、Planning 与阶段门禁、Subagent 受控委派、异步续行、由证据决定完成。</td></tr><tr><td>第 5 章</td><td>工程契约：信息</td><td>有限模型窗口与持续增长的任务世界之间如何取舍。</td><td>Context 构建管线与 Manifest、压缩与卸载、Session / Task State / Workspace 的区分、Memory 与 Knowledge 的分工、Skill 的渐进式披露。</td></tr><tr><td>第 6 章</td><td>工程契约：行动</td><td>行动意图如何被授权、执行与验证。</td><td>统一 Action Plane、Function Calling / MCP / A2A 的职责分层、Environment Contract 与 Sandbox、Permission 与 HITL、Trace 与 Evaluation 闭环。</td></tr></tbody></table><p>第一条主线是构建入口的选择。当前存在四类主要起点：高代码框架提供代码级控制；产品化 Harness 以 Coding Agent CLI、SDK 与工作区助手的形式复用成熟能力；Managed Agents 将约定范围内的 Harness 与运行基础服务化；Agent 云产品提供原生创建与共享资源入口。四类入口不构成成熟度阶梯，也不互斥，选择依据是任务结构、定制深度、数据边界、环境影响、团队能力与交付方式。当多团队、多来源 Agent 同时存在时，Agent Platform 负责统一创建、接入、规模化交付、运行、治理、协作、观测与优化，它不是第五类入口。</p><p>第二条主线把 Harness 拆为任务、信息、行动三类工程契约。任务契约解决推进与终止：Agent Loop 以 Prepare、Model、Act、Observe、Verify 推进，显式状态与多维预算提供确定性边界，完成由环境证据判定而非由模型停止判定。信息契约解决模型此刻应当看见什么：Context Builder 按身份、可信度、相关性与 Token 预算动态编译输入，压缩与卸载控制窗口增长，但任何关键事实必须先落入权威状态；Session 表达交互连续性，Task 表达可验收目标，Workspace 承载模型窗口之外的工作记忆。行动契约解决意图如何成为受控的环境事实：统一 Action Plane 按 Schema、身份、Policy、审批、执行、Observation 与 Trace 推进，Environment Contract 与 Sandbox 提供文件、进程、网络与 Secret 的真实隔离，Trace 与 Evaluation 把真实失败转化为有针对性的 Harness 改动。</p><p>三类契约存在内在顺序：任务定义流转，信息定义每一步的可见范围，行动定义副作用与验收依据。第 4 至 6 章共用同一贯穿案例，即生产服务漏洞修复与变更发布 Agent，跨章跟读同一任务比分别阅读更容易看清三类契约的咬合关系。</p><p>本篇构建出的 Agent 随后需要进入真实的执行环境、状态存储与流量通道，那是第三篇运行的主题。</p>',9)])])}const h=e(r,[["render",o]]);export{A as __pageData,h as default};
